// Serves a single sitemap on the main domain. Portfolio URLs are generated by
// the API from published portfolio sites and projects.
export const onRequest = async () => {
  try {
    const res = await fetch('https://api.careercode.com.ng/api/v1/portfolio/sitemap.xml');
    if (res.ok) {
      return new Response(await res.text(), {
        headers: {
          'Content-Type': 'application/xml; charset=utf-8',
          'Cache-Control': 'public, max-age=1800',
        },
      });
    }
  } catch { /* fall through */ }
  return new Response(
    '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"></urlset>',
    { headers: { 'Content-Type': 'application/xml; charset=utf-8' } }
  );
};
